'use client';
// Shared UI pieces. Every control is at least 56px (64px for main actions) for young hands.
import { useEffect, useId, useRef, useSyncExternalStore, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { ICON, type IconName } from '@/art/icons';
import { sfx } from '@/lib/sfx';

/** Inline SVG markup generated by our own art code (never user input). */
export function Svg({ html, className = '', label }: { html: string; className?: string; label?: string }) {
  return label
    ? <span className={className} role="img" aria-label={label} dangerouslySetInnerHTML={{ __html: html }} />
    : <span className={className} aria-hidden="true" dangerouslySetInnerHTML={{ __html: html }} />;
}

export function Icon({ name, className = 'ico' }: { name: IconName; className?: string }) {
  return <Svg html={ICON[name]} className={className} />;
}

type Variant = 'primary' | 'sun' | 'mint' | 'ghost' | 'white';
export function Button({ children, onClick, variant = 'primary', icon, xl, block = true, disabled, sub, type = 'button', className = '', sound = true, ...rest }: {
  children: ReactNode; onClick?: () => void; variant?: Variant; icon?: IconName | ReactNode; xl?: boolean; block?: boolean;
  disabled?: boolean; sub?: string; type?: 'button' | 'submit'; className?: string; sound?: boolean; 'data-autofocus'?: boolean;
}) {
  return (
    <button
      type={type}
      disabled={disabled}
      className={`btn btn-${variant}${block ? ' btn-block' : ''}${xl ? ' btn-xl' : ''} ${className}`}
      onClick={() => { if (sound) sfx('tap'); onClick?.(); }}
      {...rest}
    >
      {typeof icon === 'string' ? <Icon name={icon as IconName} /> : icon}
      {sub ? <span className="lbl">{children}<small>{sub}</small></span> : children}
    </button>
  );
}

export function IconButton({ icon, label, onClick, on, className = '' }: { icon: IconName; label: string; onClick: () => void; on?: boolean; className?: string }) {
  return (
    <button type="button" className={`icon-btn${on ? ' on' : ''} ${className}`} aria-label={label} title={label}
      aria-pressed={on === undefined ? undefined : on}
      onClick={(e) => { e.stopPropagation(); sfx('tap'); onClick(); }}>
      <Svg html={ICON[icon]} />
    </button>
  );
}

/* ---------- portal into the phone frame ---------- */
const noopSub = () => () => {};
function useDevice(): HTMLElement | null {
  const mounted = useSyncExternalStore(noopSub, () => true, () => false);
  return mounted ? document.getElementById('device') : null;
}

/** Bottom sheet. Closes with the X, the backdrop or Escape, and gives focus back to the opener. */
export function Sheet({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  const device = useDevice();
  const panel = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.stopPropagation(); closeRef.current(); } };
    document.addEventListener('keydown', onKey, true);
    const t = window.setTimeout(() => panel.current?.querySelector<HTMLElement>('[data-autofocus], button')?.focus(), 60);
    return () => { document.removeEventListener('keydown', onKey, true); window.clearTimeout(t); opener?.focus?.(); };
  }, [device]);
  if (!device) return null;
  return createPortal(
    <>
      <div className="sheet-backdrop" onClick={() => onClose()} />
      <div className="sheet" role="dialog" aria-modal="true" aria-label={title} ref={panel}>
        <div className="grab" aria-hidden="true" />
        <div className="topbar"><h2>{title}</h2><IconButton icon="close" label="Close" onClick={onClose} /></div>
        {children}
      </div>
    </>,
    device,
  );
}

/* ---------- toasts ---------- */
type ToastItem = { id: number; text: string };
let toasts: ToastItem[] = [];
let toastId = 0;
const toastSubs = new Set<() => void>();
export function toast(text: string) {
  const id = ++toastId;
  toasts = [...toasts, { id, text }];
  toastSubs.forEach((f) => f());
  window.setTimeout(() => { toasts = toasts.filter((t) => t.id !== id); toastSubs.forEach((f) => f()); }, 2700);
}
const emptyToasts: ToastItem[] = [];
export function Toaster() {
  const list = useSyncExternalStore((f) => { toastSubs.add(f); return () => { toastSubs.delete(f); }; }, () => toasts, () => emptyToasts);
  return <>{list.map((t) => <div key={t.id} className="toast" role="status">{t.text}</div>)}</>;
}

/* ---------- small controls ---------- */
export function Switch({ label, checked, onChange }: { label: string; checked: boolean; onChange: (v: boolean) => void }) {
  return <button type="button" className="switch" role="switch" aria-checked={checked} aria-label={label} onClick={() => { sfx('tap'); onChange(!checked); }} />;
}

export function GalaxyBg() {
  return <div className="galaxy-bg" aria-hidden="true"><div className="starfield" /></div>;
}

/** A unique id that is the same on the server and the client (safe for SVG gradient ids). */
export function useSvgId(prefix: string) {
  return prefix + useId().replace(/[^a-zA-Z0-9_-]/g, '');
}
